inline const SFE *GetSFE(const void *buf) {
  return ::flatbuffers::GetRoot<SFE>(buf);
}

inline const SFE *GetSizePrefixedSFE(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SFE>(buf);
}

inline const char *SFEIdentifier() {
  return "$SFE";
}

inline bool SFEBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SFEIdentifier());
}

inline bool SizePrefixedSFEBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SFEIdentifier(), true);
}

template <bool B = false>
inline bool VerifySFEBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SFE>(SFEIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSFEBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SFE>(SFEIdentifier());
}

inline void FinishSFEBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SFE> root) {
  fbb.Finish(root, SFEIdentifier());
}

inline void FinishSizePrefixedSFEBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SFE> root) {
  fbb.FinishSizePrefixed(root, SFEIdentifier());
}

inline std::unique_ptr<SFET> UnPackSFE(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SFET>(GetSFE(buf)->UnPack(res));
}

inline std::unique_ptr<SFET> UnPackSizePrefixedSFE(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SFET>(GetSizePrefixedSFE(buf)->UnPack(res));
}

